CREATE TABLE raw_digital.login_attempts (
    login_id            VARCHAR(30)   ENCODE ZSTD,
    customer_id         VARCHAR(30)   ENCODE ZSTD,
    attempted_at        TIMESTAMP     ENCODE ZSTD,
    success             BOOLEAN       ENCODE RAW,
    failure_reason      VARCHAR(120)  ENCODE ZSTD,
    channel             VARCHAR(30)   ENCODE ZSTD,
    ip_address          VARCHAR(45)   ENCODE ZSTD,
    user_agent          VARCHAR(500)  ENCODE ZSTD,
    mfa_method          VARCHAR(30)   ENCODE ZSTD,
    device_fingerprint  VARCHAR(120)  ENCODE ZSTD
)
DISTSTYLE KEY DISTKEY (customer_id) SORTKEY (attempted_at);


-- =====================================================================
-- raw_marketing
-- =====================================================================

-- campaigns
CREATE TABLE raw_marketing.campaigns (
    campaign_id        VARCHAR(30)    ENCODE ZSTD,
    campaign_name      VARCHAR(120)   ENCODE ZSTD,
    channel            VARCHAR(30)    ENCODE ZSTD,
    objective          VARCHAR(120)   ENCODE ZSTD,
    start_date         DATE           ENCODE ZSTD,
    end_date           DATE           ENCODE ZSTD,
    budget             NUMERIC(18,4)  ENCODE ZSTD,
    target_segment     VARCHAR(30)    ENCODE ZSTD,
    owner_employee_id  VARCHAR(30)    ENCODE ZSTD,
    status             VARCHAR(20)    ENCODE ZSTD
)
DISTSTYLE AUTO;

-- customer_segments
CREATE TABLE raw_marketing.customer_segments (
    segment_code  VARCHAR(30)   ENCODE ZSTD,
    segment_name  VARCHAR(80)   ENCODE ZSTD,
    description   VARCHAR(500)  ENCODE ZSTD
)
DISTSTYLE ALL;

-- customer_interactions
CREATE TABLE raw_marketing.customer_interactions (
    interaction_id         VARCHAR(30)   ENCODE ZSTD,
    customer_id            VARCHAR(30)   ENCODE ZSTD,
    campaign_id            VARCHAR(30)   ENCODE ZSTD,
    channel                VARCHAR(30)   ENCODE ZSTD,
    topic                  VARCHAR(120)  ENCODE ZSTD,
    employee_id            VARCHAR(30)   ENCODE ZSTD,
    interaction_timestamp  TIMESTAMP     ENCODE ZSTD,
    duration_minutes       INTEGER       ENCODE AZ64,
    outcome                VARCHAR(80)   ENCODE ZSTD,
    satisfaction_score     INTEGER       ENCODE AZ64,
    notes                  VARCHAR(500)  ENCODE ZSTD
)
DISTSTYLE KEY DISTKEY (customer_id) SORTKEY (interaction_timestamp);
